import { SoundKey } from "../../../logic";

interface IApplySettingsAudioProps {
  scene: Phaser.Scene;
  isInputUnlocked: boolean;
  isMusicOn: boolean;
  isSoundOn: boolean;
  musicVolume?: number;
}

const DEFAULT_MUSIC_VOLUME = 0.09;

export function applySettingsAudio({
  scene,
  isInputUnlocked,
  isMusicOn,
  isSoundOn,
  musicVolume = DEFAULT_MUSIC_VOLUME,
}: IApplySettingsAudioProps): void {
  scene.sound.mute = !isSoundOn;

  if (!isSoundOn || !isMusicOn) {
    stopMusic(scene);
    return;
  }

  if (!isInputUnlocked) {
    return;
  }

  playOrResumeMusic({
    scene,
    musicVolume,
  });
}

function playOrResumeMusic(props: { scene: Phaser.Scene; musicVolume: number }): void {
  const { scene, musicVolume } = props;
  const music = scene.sound.get(SoundKey.music) ?? scene.sound.add(SoundKey.music);

  if (music.isPlaying) {
    return;
  }

  if (music.isPaused) {
    music.resume();
    return;
  }

  music.play({
    loop: true,
    volume: musicVolume,
  });
}

function stopMusic(scene: Phaser.Scene): void {
  const music = scene.sound.get(SoundKey.music);
  if (!music) {
    return;
  }

  if (music.isPlaying || music.isPaused) {
    music.stop();
  }
}
