import { pauseParentSceneForAd, resumeParentSceneAfterAd } from "./sceneControl";

interface IAdSceneFlowProps {
  scene: Phaser.Scene;
  parentSceneKey: string;
}

interface IFinishAdSceneProps extends IAdSceneFlowProps {
  onBeforeStop?: () => void;
}

export function getParentScene(props: IAdSceneFlowProps): Phaser.Scene {
  return props.scene.scene.get(props.parentSceneKey);
}

export function startAdScene(props: IAdSceneFlowProps): Phaser.Scene {
  const parentScene = getParentScene(props);

  /**
   * Launcher глушит звук еще до launch.
   * Сцена повторяет это здесь, чтобы прямой старт тоже не оставлял хвост музыки.
   */
  pauseParentSceneForAd({ parentScene });
  return parentScene;
}

export function finishAdScene(props: IFinishAdSceneProps): void {
  props.onBeforeStop?.();
  const parentScene = getParentScene(props);
  resumeParentSceneAfterAd({ parentScene });
  props.scene.scene.stop();
}
