import { SoundKey } from "../../logic";
import { BgAssetManager } from "../shared/background";
import { SceneSoundManager } from "../shared";
import { SpiderGameScenes } from "../scenes";
import { SpiderStartView } from "./SpiderStartView";
import { SpiderStartSceneModalHandler } from "./SpiderStartSceneModalHandler";

const MUSIC_VOLUME = 0.09;

export class SpiderStartScene extends Phaser.Scene {
  constructor() {
    super(SpiderGameScenes.SpiderStart);
  }

  preload() {}

  create() {
    const scene = this;
    new BgAssetManager({ scene });
    new SceneSoundManager({
      scene,
      musicSoundKey: SoundKey.music,
      musicVolume: MUSIC_VOLUME,
    });
    new SpiderStartSceneModalHandler({ scene });
    new SpiderStartView({ scene });
  }
}
